import openpyxl

wb = openpyxl.load_workbook('test-supply.xlsx')

# Check CFC data sheet structure
if 'CFC data' in wb.sheetnames:
    ws = wb['CFC data']
    print("CFC data sheet structure:")
    for row in range(1, 40):
        row_data = []
        for col in range(1, 6):
            cell = ws.cell(row, col)
            val = cell.value
            if val or row <= 3:
                if hasattr(cell, 'value') and isinstance(val, str) and val.startswith('='):
                    row_data.append(f"{chr(64+col)}={val[:40]}")
                else:
                    row_data.append(f"{chr(64+col)}={val}")
        if row_data:
            print(f"Row {row}: {', '.join(row_data)}")

wb.close()
