python3 << 'EOF'
import openpyxl

wb = openpyxl.load_workbook('test-supply.xlsx')
ws = wb['Production']

print("Production function area (rows 35-60):")
for row in range(30, 65):
    row_data = []
    for col in range(1, 15):
        cell = ws.cell(row, col)
        val = cell.value
        if val:
            col_letter = openpyxl.utils.get_column_letter(col)
            if isinstance(val, str) and val.startswith('='):
                row_data.append(f"{col_letter}={val[:50]}")
            else:
                row_data.append(f"{col_letter}={val}")
    if row_data:
        print(f"Row {row}: {', '.join(row_data)}")

wb.close()
EOF
